<script setup>
import { onMounted, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import api from '@/api'
import { currency, dateTime, statusMap } from '@/utils/format'

const loading=ref(false);const categories=ref([]);const result=reactive({items:[],total:0});const params=reactive({keyword:'',status_filter:'',category_id:undefined,page:1,page_size:20});const dialog=ref(false);const current=ref(null);const audit=reactive({action:'approve',note:''})
const load=async()=>{loading.value=true;try{Object.assign(result,await api.get('/admin/products',{params}))}finally{loading.value=false}}
const openAudit=(row,action='approve')=>{current.value=row;audit.action=action;audit.note='';dialog.value=true}
const submit=async()=>{await api.patch(`/admin/products/${current.value.id}/audit`,audit);ElMessage.success('商品状态已更新');dialog.value=false;load()}
const quick=async(row,action)=>{await api.patch(`/admin/products/${row.id}/audit`,{action,note:''});ElMessage.success(action==='feature'?'已设为推荐':'已取消推荐');load()}
onMounted(async()=>{categories.value=await api.get('/categories');load()})
</script>
<template><div><div class="admin-filters"><el-input v-model="params.keyword" clearable placeholder="搜索商品标题" @keyup.enter="load"><template #prefix><el-icon><Search/></el-icon></template></el-input><el-select v-model="params.status_filter" clearable placeholder="商品状态" style="width:140px"><el-option v-for="(item,key) in statusMap" :key="key" v-show="['pending','published','off_shelf','rejected','sold'].includes(key)" :label="item[0]" :value="key"/></el-select><el-select v-model="params.category_id" clearable placeholder="商品分类" style="width:160px"><el-option v-for="item in categories" :key="item.id" :label="item.name" :value="item.id"/></el-select><el-button type="success" @click="params.page=1;load()">查询</el-button><el-button @click="Object.assign(params,{keyword:'',status_filter:'',category_id:undefined,page:1});load()">重置</el-button><span class="filter-count">共 {{result.total}} 件商品</span></div><section class="admin-card"><el-table v-loading="loading" :data="result.items"><el-table-column label="商品" min-width="290"><template #default="{row}"><div class="table-product"><img :src="row.images[0]"/><div><strong>{{row.title}}</strong><small>{{row.category?.name}} · {{row.condition}}</small></div></div></template></el-table-column><el-table-column label="卖家" min-width="130"><template #default="{row}">{{row.seller?.nickname}}<small class="block">{{row.seller?.campus}}</small></template></el-table-column><el-table-column label="价格"><template #default="{row}"><strong class="price-text">{{currency(row.price)}}</strong></template></el-table-column><el-table-column label="数据" min-width="125"><template #default="{row}"><span>{{row.view_count}} 浏览</span><small class="block">{{row.favorite_count}} 收藏</small></template></el-table-column><el-table-column label="推荐"><template #default="{row}"><el-switch :model-value="row.featured" active-color="#2b7b3e" @change="quick(row,row.featured?'unfeature':'feature')"/></template></el-table-column><el-table-column label="状态"><template #default="{row}"><el-tag :type="statusMap[row.status]?.[1]">{{statusMap[row.status]?.[0]}}</el-tag></template></el-table-column><el-table-column label="发布时间" width="150"><template #default="{row}">{{dateTime(row.created_at)}}</template></el-table-column><el-table-column label="操作" width="185" fixed="right"><template #default="{row}"><template v-if="row.status==='pending'"><el-button size="small" type="success" @click="openAudit(row,'approve')">通过</el-button><el-button size="small" type="danger" plain @click="openAudit(row,'reject')">驳回</el-button></template><template v-else><el-button size="small" @click="$router.push(`/product/${row.id}`)">查看</el-button><el-button v-if="row.status==='published'" size="small" type="danger" plain @click="openAudit(row,'off_shelf')">下架</el-button><el-button v-if="row.status==='off_shelf'" size="small" type="success" plain @click="openAudit(row,'restore')">恢复</el-button></template></template></el-table-column></el-table><div class="pagination-row"><el-pagination v-model:current-page="params.page" background layout="total,prev,pager,next" :total="result.total" :page-size="params.page_size" @current-change="load"/></div></section><el-dialog v-model="dialog" :title="{approve:'通过审核',reject:'驳回商品',off_shelf:'下架商品',restore:'恢复商品'}[audit.action]" width="480px"><div v-if="current" class="audit-product"><img :src="current.images[0]"/><div><strong>{{current.title}}</strong><span>{{currency(current.price)}} · {{current.seller?.nickname}}</span></div></div><el-form label-position="top"><el-form-item label="审核意见 / 操作原因"><el-input v-model="audit.note" type="textarea" :rows="4" placeholder="审核通过可留空，驳回或下架请说明原因"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button :type="audit.action==='approve'||audit.action==='restore'?'success':'danger'" @click="submit">确认</el-button></template></el-dialog></div></template>
<style scoped>.filter-count{margin-left:auto;color:#818a84;font-size:12px}.block{display:block;margin-top:4px;color:#929b95;font-size:10px}.price-text{color:#df572d}.audit-product{display:flex;align-items:center;gap:12px;padding:12px;margin-bottom:16px;border-radius:8px;background:#f5f7f4}.audit-product img{width:75px;height:64px;object-fit:cover;border-radius:6px}.audit-product strong,.audit-product span{display:block}.audit-product span{margin-top:6px;color:#7d877f;font-size:12px}</style>

